git log --author="$E" --no-merges --shortstat --format='@%h' | awk '/^@/{next} /changed/{f+=$1;i+=$4;d+=$6}END{print f,i,d}'
{
echo "commit,date_utc,author_email,committer_email,type,files_changed,insertions,deletions,subject"
git log --author="$E" --format='@%h|%H|%aI|%ae|%ce|%P|%s' --shortstat | awk -F'|' '
/^@/{ if(h)out(); h=1; sub(/^@/,"",$1); c=$1; d=$3; ae=$4; ce=$5; n=split($6,p," "); t=(n>1)?"merge":"commit"; s=$7; for(k=8;k<=NF;k++)s=s"|"$k; fi=0;ins=0;del=0; next}
/changed/{ fi=$1; ins=0; del=0; for(k=1;k<=NF;k++){ if($k ~ /insertion/) ins=$(k-1); if($k ~ /deletion/) del=$(k-1)} }
function out(){ gsub(/"/,"\"\"",s); printf "%s,%s,%s,%s,%s,%d,%d,%d,\"%s\"\n",c,d,ae,ce,t,fi,ins,del,s }
END{out()}'
} > $O/contribution-commits.csv
wc -l $O/contribution-commits.csv; head -4 $O/contribution-commits.csv
git log --author="$E" --no-merges --name-only --format= | grep -v '^$' | sed 's/.*\.//' | sort | uniq -c | sort -rn | head"}
